import { describe, expect, it, vi } from "vitest";
import { AgentSession } from "./agent-session.ts";
import type { ExtensionRunner } from "./extensions/runner.ts";
import type { ResolvedCommand } from "./extensions/types.ts";
import { SettingsManager } from "./settings-manager.ts";

function createMockSession({
	enabled,
	threshold = 128_000,
	tokens,
	mode = "tui",
	command,
}: {
	enabled: boolean;
	threshold?: number;
	tokens: number | null;
	mode?: "tui" | "print" | "rpc";
	command?: ResolvedCommand | undefined;
}) {
	const settings = SettingsManager.inMemory({
		autoHandoff: { enabled, thresholdTokens: threshold },
	});

	const getCommand = vi.fn(() => command);
	const handler = command?.handler ?? vi.fn();
	const createCommandContext = vi.fn(() => ({ mock: "ctx" }) as unknown as never);
	const emitError = vi.fn();

	const extensionRunner = {
		getCommand,
		createCommandContext,
		emitError,
		emit: vi.fn(),
	} as unknown as ExtensionRunner;

	const resourceLoader = {
		getExtensions: () => ({ extensions: [], errors: [], runtime: { flagValues: new Map(), pendingProviderRegistrations: [], assertActive: () => {} } }),
		getSkills: () => ({ skills: [], diagnostics: [] }),
		getPrompts: () => ({ prompts: [], diagnostics: [] }),
		getThemes: () => ({ themes: [], diagnostics: [] }),
		getAgents: () => ({ agents: [], diagnostics: [] }),
		getAgentsFiles: () => ({ agentsFiles: [] }),
		getSystemPrompt: () => undefined,
		getAppendSystemPrompt: () => [],
		getExtensionDiagnostics: () => [],
		extendResources: () => {},
		reload: vi.fn(),
	};

	const modelRegistry = {
		registerProvider: vi.fn(),
		unregisterProvider: vi.fn(),
		getProvider: vi.fn(),
		getProviders: vi.fn(() => []),
		getModels: vi.fn(() => []),
	};

	const agent = {
		state: { messages: [], tools: [] },
		subscribe: vi.fn(() => () => {}),
	};

	const session = new AgentSession({
		agent: agent as unknown as never,
		sessionManager: { getBranch: () => [] } as unknown as never,
		settingsManager: settings,
		cwd: "/tmp",
		resourceLoader: resourceLoader as unknown as never,
		modelRegistry: modelRegistry as unknown as never,
	});

	(session as any)._extensionRunner = extensionRunner;
	(session as any)._extensionMode = mode;
	(session as any).getContextUsage = () =>
